$ErrorActionPreference='Stop'
Add-Type -AssemblyName System.Drawing
Add-Type -ReferencedAssemblies System.Drawing -TypeDefinition @'
using System;
using System.Drawing;
using System.Collections.Generic;
public static class K094Check {
 public static int[] Info(Bitmap b){int l=b.Width,t=b.Height,r=-1,bot=-1,min=255,max=0,clear=0;for(int y=0;y<b.Height;y++)for(int x=0;x<b.Width;x++){var p=b.GetPixel(x,y);if(p.A==0){clear++;continue;}l=Math.Min(l,x);t=Math.Min(t,y);r=Math.Max(r,x);bot=Math.Max(bot,y);min=Math.Min(min,p.A);max=Math.Max(max,p.A);}return new[]{l,t,r,bot,min,max,clear};}
 public static int Groups(Bitmap b){int groups=0;var seen=new bool[b.Width,b.Height];for(int y=0;y<b.Height;y++)for(int x=0;x<b.Width;x++){if(seen[x,y]||b.GetPixel(x,y).A==0)continue;groups++;var q=new Queue<Point>();q.Enqueue(new Point(x,y));seen[x,y]=true;while(q.Count>0){var p=q.Dequeue();for(int j=-1;j<=1;j++)for(int i=-1;i<=1;i++){int nx=p.X+i,ny=p.Y+j;if(nx>=0&&ny>=0&&nx<b.Width&&ny<b.Height&&!seen[nx,ny]&&b.GetPixel(nx,ny).A>0){seen[nx,ny]=true;q.Enqueue(new Point(nx,ny));}}}}return groups;}
 public static bool Scaled(Bitmap a,Bitmap b,int n){if(b.Width!=a.Width*n||b.Height!=a.Height*n)return false;for(int y=0;y<b.Height;y++)for(int x=0;x<b.Width;x++)if(a.GetPixel(x/n,y/n).ToArgb()!=b.GetPixel(x,y).ToArgb())return false;return true;}
 public static bool FrameAt(Bitmap sheet,Bitmap frame,int x,int y){for(int j=0;j<frame.Height;j++)for(int i=0;i<frame.Width;i++){var a=sheet.GetPixel(i+x,j+y);var b=frame.GetPixel(i,j);if((a.A!=0||b.A!=0)&&a.ToArgb()!=b.ToArgb())return false;}return true;}
 public static bool Ring(Bitmap b,int r){int c=r+2,count=0;for(int y=0;y<b.Height;y++)for(int x=0;x<b.Width;x++){int a=b.GetPixel(x,y).A;if(a!=0&&a!=255)return false;if(a==255){count++;if(Math.Abs(Math.Sqrt((x-c)*(x-c)+(y-c)*(y-c))-r)>.6)return false;}}return count>r;}
}
'@
$out=$PSScriptRoot
function Bmp($p){[Drawing.Bitmap]::FromFile((Join-Path $out $p))}
function Assert($condition,$message){if(!$condition){throw $message}}
$checks=[Collections.Generic.List[string]]::new();$assets=@();$names=@('buried','armed','selected','ghost','ghost_invalid')
foreach($file in Get-ChildItem $out -Recurse -Filter '*.png' | Where-Object FullName -NotMatch '\\qa\\'){
 $relative=$file.FullName.Substring($out.Length+1).Replace('\','/');$b=[Drawing.Bitmap]::FromFile($file.FullName);$info=[K094Check]::Info($b)
 $asset=[ordered]@{file=$relative;width=$b.Width;height=$b.Height;format='RGBA PNG';boundsInclusive=@($info[0],$info[1],$info[2],$info[3]);nonzeroAlphaMin=$info[4];nonzeroAlphaMax=$info[5];transparentPixels=$info[6];sha256=(Get-FileHash -LiteralPath $file.FullName -Algorithm SHA256).Hash.ToLower()}
 if($relative.StartsWith('icons/')){Assert ($b.Width -eq 24 -and $b.Height -eq 24) '아이콘 크기';Assert ($info[6] -gt 0) '아이콘 투명 바탕';$asset.pivotTopLeft=@(12,12);$asset.frameOrder=@($file.BaseName);$asset.components8=[K094Check]::Groups($b);if($file.BaseName -notmatch 'selected'){Assert ($asset.components8 -eq 1) '아이콘의 분리된 화소';$checks.Add("$relative : 단일 연결 덩어리, 바깥 투명 여백")}else{Assert ($asset.components8 -le 5) '선택 모서리 이외 분리 화소'};if($relative -match 'ghost'){Assert ($info[4] -eq 114 -and $info[5] -eq 114) '미리보기 투명도'}else{Assert ($info[4] -eq 255 -and $info[5] -eq 255) '아이콘 가장자리 알파'}}
 if($relative -match '^rings/.+_r(\d+)_(line|fill|combined)\.png$'){$r=[int]$Matches[1];$layer=$Matches[2];Assert ($b.Width -eq (2*$r+5) -and $b.Height -eq (2*$r+5)) '범위 원 크기';$asset.pivotTopLeft=@(($r+2),($r+2));$asset.radiusPixels=$r;$asset.layer=$layer;if($layer -eq 'line'){Assert ([K094Check]::Ring($b,$r)) '원 가장자리 1화소와 반경';$checks.Add("$relative : 정수 화소 점선, 반경 오차 0.6화소 이내, 가장자리 알파 255")};if($layer -eq 'fill'){Assert ($info[5] -le 30) '부드러운 내부 채움 알파'}}
 if($relative -match '^effects/dig_\d\.png$'){Assert ($b.Width -eq 32 -and $b.Height -eq 32) '먼지 크기';Assert ([K094Check]::Groups($b) -eq 1) '먼지 분리 화소';$asset.pivotTopLeft=@(16,26)}
 $assets+=,$asset;$b.Dispose()
}
foreach($pair in @(@('trap_bomb_states_native_96x128.png','trap_bomb_states_game_288x384.png'),@('dig_native_96x128_4f.png','dig_game_288x384_4f.png'))){$a=Bmp "sheets/$($pair[0])";$b=Bmp "sheets/$($pair[1])";Assert ([K094Check]::Scaled($a,$b,3)) '3배 최근접 불일치';$checks.Add("$($pair[1]) : 모든 화소가 원본의 정확한 3×3 복제");$a.Dispose();$b.Dispose()}
$native=Bmp 'sheets/trap_bomb_states_native_96x128.png';$map=Bmp 'sheets/trap_bomb_map_states.png'
for($i=0;$i -lt 5;$i++){$icon=Bmp "icons/trap_bomb_$($names[$i]).png";Assert ([K094Check]::FrameAt($map,$icon,($i*24),0)) '지도 상태 순서';Assert ([K094Check]::FrameAt($native,$icon,($i*96+36),97)) '매설 기준점 불일치';$icon.Dispose()};$native.Dispose();$map.Dispose();$checks.Add('상태 5장 순서·지도 중심 (12,12)·공통 매설 기준선 y=120 일치')
$native=Bmp 'sheets/dig_native_96x128_4f.png';$map=Bmp 'effects/dig_map_4f.png'
for($i=0;$i -lt 4;$i++){$frame=Bmp "effects/dig_$i.png";Assert ([K094Check]::FrameAt($map,$frame,($i*32),0)) '먼지 지도 순서';Assert ([K094Check]::FrameAt($native,$frame,($i*96+32),94)) '먼지 기준점';$frame.Dispose()};$native.Dispose();$map.Dispose();$checks.Add('먼지 4장 순서·매설점 (16,26) → (48,120) 일치; 상승은 의도된 동작')
foreach($file in Get-ChildItem (Join-Path $out 'previews') -Filter '*.png'){$p=$file.BaseName.Replace('_4x','');$source=switch -Regex ($p){'^trap_bomb_map_states$' {'sheets/trap_bomb_map_states.png';break};'^trap_bomb_' {"icons/$p.png";break};'^dig_map_4f$' {'effects/dig_map_4f.png';break};'^radius_' {"rings/$($p)_r64_combined.png";break}};$a=Bmp $source;$b=[Drawing.Bitmap]::FromFile($file.FullName);Assert ([K094Check]::Scaled($a,$b,4)) '4배 보기 불일치';$a.Dispose();$b.Dispose()};$checks.Add('모든 4배 보기는 최근접 확대와 화소 단위 일치')
$manifest=[ordered]@{
 card='K-094';version=1;status='그림 제작 완료 · 게임 연결 및 사용자 외형 검토 대기';trapKinds=@(@{id='trap_bomb';label='폭발 함정';source='Game/Assets/_Project/Data/Traps/trap_bomb.asset';damageRadiusDefaultMeters=10;radiusSource='Game/Assets/_Project/Core/Definitions/TrapDef.cs'});
 scale=@{mapPixelsPer5Meters=32;mapPixelsPerMeter=6.4;iconCanvas=@(24,24);iconArtMaxPixels=24;mapPivotTopLeft=@(12,12);filter='Point';compression='None';coordinateConvention='원점 왼쪽 위, x 오른쪽, y 아래';unityNormalizedMapPivot=@(.5,.5)};
 stateOrder=$names;mapStateSheet=@{file='sheets/trap_bomb_map_states.png';cell=@(24,24);frames=5;pivotTopLeft=@(12,12)};
 dust=@{file='effects/dig_map_4f.png';cell=@(32,32);frameOrder=@('dig_0','dig_1','dig_2','dig_3');fps=10;loop=$false;durationSeconds=.4;pivotTopLeft=@(16,26);unityNormalizedPivot=@(.5,.1875);intentionalRisePixels=@(0,1,3,5)};
 commonSheets=@{trapNative='sheets/trap_bomb_states_native_96x128.png';trapGame='sheets/trap_bomb_states_game_288x384.png';trapFrames=5;trapOrder=$names;dustNative='sheets/dig_native_96x128_4f.png';dustGame='sheets/dig_game_288x384_4f.png';dustFrames=4;nativeCell=@(96,128);gameCell=@(288,384);nativeBurialPivot=@(48,120);gameBurialPivot=@(144,360);unityNormalizedPivot=@(.5,.0625);note='사람의 발 대신 매설점'};
 rings=@{colors=@{valid_brass='#d5b16b';valid_green='#9abe77';invalid='#e16d61'};radiiPixels=@(32,64,96,128);radiiMeters=@(5,10,15,20);canvasFormula='2 * radius + 5';pivotFormula='radius + 2';linePixels=1;dashPixels=4;gapPixels=4;fillAlphaByteRange=@(8,30);layerOrder=@('fill','line','icon');scalableFiles=@('rings/radius_valid_brass_scalable.svg','rings/radius_valid_green_scalable.svg','rings/radius_invalid_scalable.svg');scalingNote='PNG 선을 확대하지 말고 최종 화면 반경으로 재생성. SVG는 vector-effect=non-scaling-stroke. Unity 벡터 지원 여부는 연결 담당 확인. 패키지 변경 없음.';geometry='정수 중점 원 알고리즘 + 원주 거리 4화소 켜짐/4화소 꺼짐; 가장자리 알파 255';defaultDamageRadiusPixels=64};
 mockup=@{file='mockup_free_placement.png';base='map_base_current_tiles.png';source='Game/Assets/_Project/Art/UI/Resources/TrapMap/';actualGameCapture=$false;positionsPixels=@(@(307,114),@(451,177),@(569,284),@(184,371),@(662,145));description='현재 게임 타일 재조합. 자유 좌표 예시이며 실제 지형·설치 판정 아님.'};
 replacements=@();sourceGeneration=@{tool='내장 image_gen';original='source/generated.png';postprocess='두 피사체 영역별 불투명 경계 추출, 20×20 및 28×18 최근접 샘플, 제한 팔레트, 가장 큰 연결 덩어리 보존, 아이콘 외곽선, 상태 겉칠, 먼지 크기·상승·투명도 변환';prompt='Use case: stylized-concept. Create a production pixel-art source sheet for Human Last Rampart top-down tactical map. Transparent background, no text. TWO distinct isolated subjects horizontally side by side with huge transparent margins, no frame borders: LEFT a small buried medieval black-powder explosive trap viewed strictly top-down: round compact brown soil disturbed patch, a partially buried brass/dark iron cap, tiny red fuse nub; no modern landmine, no perspective side wall. RIGHT a small ochre/brown dig dust puff, a compact irregular cloud with 3 connected rounded lobes, designed for a burial effect. Strong chunky readable pixel clusters, dark 1-pixel-looking outline, three tones per material, muted olive brown dirt, aged brass and warm pale ochre dust. Low resolution game sprite aesthetic, designed to reduce trap to 20x20 pixels and cloud to 24x16 pixels, absolutely no tiny photorealistic texture, no blur, no glow, no lettering. Two subjects only, centers at quarter and three-quarter of canvas, same apparent size. Preserve actual transparent alpha. Palette/style compatible with muted olive/brass medieval top-down map and Octopath-inspired chunky sprites.'};
 verification=@{assetChecks=$checks.ToArray();unityRun=$false;gameModified=$false;gitWrites=$false;browserEvidence='qa/browser_check.json';limitations=@('실제 지도 판정·포인터 연동은 Claude 연결 작업','Unity Play·실제 캡처·사용자 외형 승인 미수행')};assets=$assets
}
$manifest.commonSheets.note='사람의 발 대신 매설점으로 기준선을 사용. 지도용 표식은 중심 기준.'
[IO.File]::WriteAllText((Join-Path $out 'manifest.json'),($manifest|ConvertTo-Json -Depth 12),[Text.UTF8Encoding]::new($false))
[IO.File]::WriteAllText((Join-Path $out 'qa/asset_checks.json'),(@{result='통과';checks=$checks.ToArray();pngCount=$assets.Count}|ConvertTo-Json -Depth 8),[Text.UTF8Encoding]::new($false))
Write-Output "검증 통과: PNG $($assets.Count)장 / 검사 $($checks.Count)항목"
